// Command gen writes the design tokens of tokens.json as CSS variables for the
// web (css/tokens.css), and as constants for SwiftUI (native/Tokens.swift) and
// Jetpack Compose (native/Tokens.kt). tokens.json is the one source: edit it,
// then run go generate ./pkg/web. Usage: gen <design dir> [<gallery out dir>].
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"math"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
)

const (
	// header starts every generated file, so nobody edits one by hand.
	header = "Generated by pkg/design/gen from pkg/design/tokens.json. Edit that file, then run go generate ./pkg/web."
	// springSamples is how many points a spring's CSS linear() has: enough
	// that the overshoot reads as a curve, few enough to stay one line.
	springSamples = 40
)

// pair is one key of a JSON object, kept in the order of the file: the
// generated files follow it.
type pair struct {
	k string
	v json.RawMessage
}

func object(raw json.RawMessage) []pair {
	d := json.NewDecoder(bytes.NewReader(raw))
	d.UseNumber()
	must(d.Token())
	var ps []pair
	for d.More() {
		k := must(d.Token()).(string)
		var v json.RawMessage
		check(d.Decode(&v))
		ps = append(ps, pair{k, v})
	}
	return ps
}

func field(ps []pair, k string) json.RawMessage {
	for _, p := range ps {
		if p.k == k {
			return p.v
		}
	}
	panic("tokens.json has no " + k)
}

func decode[T any](raw json.RawMessage) (v T) {
	check(json.Unmarshal(raw, &v))
	return v
}

type color struct{ Light, Dark, LightContrast, DarkContrast string }

// contrast is the value under Increase Contrast: its own, or the plain one.
func (c color) contrast(dark bool) string {
	if dark {
		return or(c.DarkContrast, c.Dark)
	}
	return or(c.LightContrast, c.Light)
}

type spring struct{ Damping, Response float64 }

type tokens struct {
	root                      []pair
	font                      map[string]string
	colors, shadows           []pair
	eases                     []pair
	typeScale, radius, shapes []pair
}

func main() {
	dir := os.Args[1]
	root := object(must(os.ReadFile(filepath.Join(dir, "tokens.json"))))
	t := tokens{
		root: root, font: decode[map[string]string](field(root, "font")), colors: object(field(root, "color")), shadows: object(field(root, "shadow")),
		eases: object(field(root, "ease")), typeScale: object(field(root, "type")), radius: object(field(root, "radius")), shapes: object(field(root, "shape")),
	}
	write(filepath.Join(dir, "css", "tokens.css"), t.css())
	write(filepath.Join(dir, "native", "Tokens.swift"), t.swift())
	write(filepath.Join(dir, "native", "Tokens.kt"), t.kotlin())
	if len(os.Args) > 2 {
		gallery(dir, os.Args[2])
	}
}

// ---- CSS ----

func (t tokens) css() string {
	var b strings.Builder
	v := func(k, val string) { fmt.Fprintf(&b, "  --%s: %s;\n", k, val) }
	fmt.Fprintf(&b, "/* %s\n   Theme: data-theme=\"light|dark\" on any element, else the system's. data-contrast=\"more\" forces Increase Contrast. */\n:root {\n", header)
	for _, k := range []string{"text", "display", "mono"} {
		v("font-"+k, t.font[k])
	}
	for _, p := range t.typeScale {
		s := decode[[4]float64](p.v)
		fam := "var(--font-text)"
		if p.k == "mono" {
			fam = "var(--font-mono)"
		}
		v("text-"+p.k, fmt.Sprintf("%s %spx/%spx %s", num(s[2]), num(s[0]), num(s[1]), fam))
		v("tracking-"+p.k, num(s[3])+"em")
	}
	for _, s := range decode[[]float64](field(t.root, "space")) {
		v("space-"+num(s), num(s)+"px")
	}
	for _, p := range t.radius {
		if p.k == "full" {
			v("radius-full", string(p.v)+"px")
			continue
		}
		v("radius-"+p.k, "calc("+string(p.v)+"px * var(--corner-k))")
	}
	for _, p := range t.shapes {
		v("radius-"+p.k, "var(--radius-"+string(p.v)+")")
	}
	v("corner-k", "1")
	for _, g := range []string{"control", "icon"} {
		for _, p := range object(field(t.root, g)) {
			v(g+"-"+p.k, string(p.v)+"px")
		}
	}
	for _, p := range object(field(t.root, "duration")) {
		v("duration-"+p.k, string(p.v)+"ms")
	}
	for _, p := range t.eases {
		if p.v[0] == '[' {
			c := decode[[4]float64](p.v)
			v("ease-"+p.k, fmt.Sprintf("cubic-bezier(%s, %s, %s, %s)", num(c[0]), num(c[1]), num(c[2]), num(c[3])))
		} else {
			v("ease-"+p.k, linear(decode[spring](p.v)))
		}
	}
	fr := decode[struct{ Blur, Saturate float64 }](field(t.root, "frosted"))
	v("frosted-blur", num(fr.Blur)+"px")
	v("frosted-saturate", num(fr.Saturate*100)+"%")
	for _, p := range object(field(t.root, "z")) {
		v("z-"+p.k, string(p.v))
	}
	fo := decode[map[string]float64](field(t.root, "focus"))
	v("hairline", "1px")
	v("focus-width", num(fo["width"])+"px")
	v("focus-offset", num(fo["offset"])+"px")
	v("focus-soft-width", num(fo["soft-width"])+"px")
	b.WriteString("}\n\n")

	theme := func(dark, contrast bool, indent string) {
		for _, p := range t.colors {
			c := decode[color](p.v)
			val := pick(dark, c.Light, c.Dark)
			if contrast {
				val = c.contrast(dark)
			}
			fmt.Fprintf(&b, "%s--color-%s: %s;\n", indent, p.k, val)
		}
		for _, p := range t.shadows {
			s := decode[color](p.v)
			fmt.Fprintf(&b, "%s--shadow-%s: %s;\n", indent, p.k, pick(dark, s.Light, s.Dark))
		}
		if contrast { // no half-pixel lines and no see-through material
			fmt.Fprintf(&b, "%s--hairline: 1px;\n%s--color-frosted: var(--color-floating);\n%s--frosted-blur: 0px;\n", indent, indent, indent)
		}
	}
	block := func(sel string, dark, contrast bool, scheme string) {
		b.WriteString(sel + " {\n")
		if scheme != "" {
			b.WriteString("  color-scheme: " + scheme + ";\n")
		}
		theme(dark, contrast, "  ")
		b.WriteString("}\n")
	}
	block(`:root, [data-theme="light"]`, false, false, "light")
	block(`[data-theme="dark"]`, true, false, "dark")
	b.WriteString("@media (prefers-color-scheme: dark) {\n")
	block(`:root:not([data-theme="light"])`, true, false, "dark")
	b.WriteString("}\n\n/* Increase Contrast: stronger secondary text, lines, separators and floating edges. */\n@media (prefers-contrast: more) {\n")
	block(`:root, [data-theme="light"]`, false, true, "")
	block(`[data-theme="dark"]`, true, true, "")
	b.WriteString("}\n@media (prefers-contrast: more) and (prefers-color-scheme: dark) {\n")
	block(`:root:not([data-theme="light"])`, true, true, "")
	b.WriteString("}\n")
	block(`[data-contrast="more"], [data-contrast="more"] [data-theme="light"]`, false, true, "")
	block(`[data-contrast="more"][data-theme="dark"], [data-contrast="more"] [data-theme="dark"], [data-theme="dark"] [data-contrast="more"]:not([data-theme="light"])`, true, true, "")
	return b.String()
}

// linear samples a damped spring over its settle time as CSS linear().
func linear(s spring) string {
	w := 2 * math.Pi / s.Response
	z := s.Damping
	wd := w * math.Sqrt(1-z*z)
	end := 4 / (z * w)
	pts := make([]string, springSamples+1)
	for i := range pts {
		t := float64(i) / springSamples * end
		x := 1 - math.Exp(-z*w*t)*(math.Cos(wd*t)+(z*w/wd)*math.Sin(wd*t))
		if i == springSamples {
			x = 1
		}
		pts[i] = num(must(strconv.ParseFloat(strconv.FormatFloat(x, 'f', 4, 64), 64)))
	}
	return "linear(" + strings.Join(pts, ", ") + ")"
}

// ---- native ----

var rgba = regexp.MustCompile(`^rgba\((\d+),\s*(\d+),\s*(\d+),\s*([\d.]+)\)$`)

// channels is a CSS color as red, green, blue and alpha from 0 to 1.
func channels(css string) [4]float64 {
	if m := rgba.FindStringSubmatch(css); m != nil {
		var c [4]float64
		for i := range c {
			c[i] = must(strconv.ParseFloat(m[i+1], 64))
			if i < 3 {
				c[i] /= 255
			}
		}
		return c
	}
	h := strings.TrimPrefix(css, "#")
	if len(h) != 6 {
		panic("color not #rrggbb or rgba(): " + css)
	}
	n := must(strconv.ParseUint(h, 16, 32))
	return [4]float64{float64(n>>16) / 255, float64(n>>8&255) / 255, float64(n&255) / 255, 1}
}

// layer is one shadow of a CSS box-shadow list: "x y blur color".
type layer struct {
	x, y, blur float64
	color      string
}

func layers(css string) []layer {
	var ls []layer
	for _, m := range regexp.MustCompile(`(-?[\d.]+)(?:px)? (-?[\d.]+)(?:px)? ([\d.]+)(?:px)? (?:-?[\d.]+(?:px)? )?(rgba\([^)]*\)|#[0-9A-Fa-f]{6})`).FindAllStringSubmatch(css, -1) {
		ls = append(ls, layer{must(strconv.ParseFloat(m[1], 64)), must(strconv.ParseFloat(m[2], 64)), must(strconv.ParseFloat(m[3], 64)), m[4]})
	}
	return ls
}

func (t tokens) swift() string {
	var b strings.Builder
	col := func(css string) string {
		c := channels(css)
		return fmt.Sprintf("Color(.sRGB, red: %s, green: %s, blue: %s, opacity: %s)", f4(c[0]), f4(c[1]), f4(c[2]), f4(c[3]))
	}
	weights := map[float64]string{300: ".light", 400: ".regular", 500: ".medium", 600: ".semibold", 700: ".bold"}
	fmt.Fprintf(&b, `// %s
// CSS --color-text-2 = Mp.color.text2. Sizes in pt (CSS px = pt). Use the colors through MpColor.resolve.
import SwiftUI

public struct MpColor: Sendable {
    public let light, dark, lightContrast, darkContrast: Color
    public func resolve(_ scheme: ColorScheme, _ contrast: ColorSchemeContrast = .standard) -> Color {
        switch (scheme, contrast) {
        case (.dark, .increased): darkContrast
        case (.dark, _): dark
        case (_, .increased): lightContrast
        default: light
        }
    }
}
public struct MpType: Sendable { public let size, lineHeight: CGFloat; public let weight: Font.Weight; public let trackingEm: CGFloat }
public struct MpShadowLayer: Sendable { public let x, y, blur: CGFloat; public let color: Color }
public struct MpShadow: Sendable { public let light, dark: [MpShadowLayer] }
public struct MpCurve: Sendable { public let x1, y1, x2, y2: Double }
public struct MpSpring: Sendable { public let response, dampingFraction: Double }

public enum Mp {
    public enum font {
        public static let text = %q
        public static let display = %q
    }
`, header, family(t.font["text"]), family(t.font["display"]))
	b.WriteString("    public enum color {\n")
	for _, p := range t.colors {
		c := decode[color](p.v)
		fmt.Fprintf(&b, "        public static let %s = MpColor(light: %s, dark: %s, lightContrast: %s, darkContrast: %s)\n", camel(p.k), col(c.Light), col(c.Dark), col(c.contrast(false)), col(c.contrast(true)))
	}
	b.WriteString("    }\n    public enum type {\n")
	for _, p := range t.typeScale {
		s := decode[[4]float64](p.v)
		fmt.Fprintf(&b, "        public static let %s = MpType(size: %s, lineHeight: %s, weight: %s, trackingEm: %s)\n", camel(p.k), num(s[0]), num(s[1]), weights[s[2]], num(s[3]))
	}
	fmt.Fprintf(&b, "    }\n    public static let space: [CGFloat] = [%s]\n", strings.Join(nums(decode[[]float64](field(t.root, "space"))), ", "))
	b.WriteString("    public enum radius {\n")
	for _, p := range t.radius {
		fmt.Fprintf(&b, "        public static let %s: CGFloat = %s\n", ident(p.k, "r"), string(p.v))
	}
	for _, p := range t.shapes {
		fmt.Fprintf(&b, "        public static let %s: CGFloat = %s\n", camel(p.k), string(p.v))
	}
	b.WriteString("        /// Corners are continuous: RoundedRectangle(cornerRadius: r, style: .continuous).\n    }\n")
	for _, g := range []string{"control", "icon"} {
		fmt.Fprintf(&b, "    public enum %s {\n", g)
		for _, p := range object(field(t.root, g)) {
			fmt.Fprintf(&b, "        public static let %s: CGFloat = %s\n", camel(p.k), string(p.v))
		}
		b.WriteString("    }\n")
	}
	b.WriteString("    public enum duration {\n")
	for _, p := range object(field(t.root, "duration")) {
		fmt.Fprintf(&b, "        public static let %s: TimeInterval = %s\n", camel(p.k), num(decode[float64](p.v)/1000))
	}
	b.WriteString("    }\n    public enum ease {\n")
	for _, p := range t.eases {
		if p.v[0] == '[' {
			c := decode[[4]float64](p.v)
			fmt.Fprintf(&b, "        public static let %s = MpCurve(x1: %s, y1: %s, x2: %s, y2: %s)\n", swiftName(camel(p.k)), num(c[0]), num(c[1]), num(c[2]), num(c[3]))
		} else {
			s := decode[spring](p.v)
			fmt.Fprintf(&b, "        public static let %s = MpSpring(response: %s, dampingFraction: %s)\n", camel(p.k), num(s.Response), num(s.Damping))
		}
	}
	b.WriteString("    }\n    public enum shadow {\n")
	sl := func(css string) string {
		var out []string
		for _, l := range layers(css) {
			out = append(out, fmt.Sprintf("MpShadowLayer(x: %s, y: %s, blur: %s, color: %s)", num(l.x), num(l.y), num(l.blur), col(l.color)))
		}
		return "[" + strings.Join(out, ", ") + "]"
	}
	for _, p := range t.shadows {
		s := decode[color](p.v)
		fmt.Fprintf(&b, "        public static let %s = MpShadow(light: %s, dark: %s)\n", ident(p.k, "s"), sl(s.Light), sl(s.Dark))
	}
	b.WriteString("    }\n}\n")
	return b.String()
}

func (t tokens) kotlin() string {
	var b strings.Builder
	col := func(css string) string {
		c := channels(css)
		return fmt.Sprintf("Color(0x%02X%02X%02X%02X)", int(math.Round(c[3]*255)), int(math.Round(c[0]*255)), int(math.Round(c[1]*255)), int(math.Round(c[2]*255)))
	}
	fmt.Fprintf(&b, `// %s
// CSS --color-text-2 = MpTheme.color.text2. Sizes in dp and sp (CSS px = dp).
package ai.mainplane.design

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.Dp
import androidx.compose.ui.unit.TextUnit
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp

data class MpColor(val light: Color, val dark: Color, val lightContrast: Color, val darkContrast: Color) {
    fun resolve(dark: Boolean, contrast: Boolean = false): Color = when {
        dark && contrast -> darkContrast
        dark -> this.dark
        contrast -> lightContrast
        else -> light
    }
}
data class MpType(val size: TextUnit, val lineHeight: TextUnit, val weight: FontWeight, val trackingEm: Float)
data class MpShadowLayer(val x: Dp, val y: Dp, val blur: Dp, val color: Color)
data class MpShadow(val light: List<MpShadowLayer>, val dark: List<MpShadowLayer>)
data class MpCurve(val x1: Float, val y1: Float, val x2: Float, val y2: Float)
/** For spring(dampingRatio, stiffness) at mass 1. */
data class MpSpring(val dampingRatio: Float, val stiffness: Float)

object MpTheme {
    object font {
        const val text = %q
        const val display = %q
    }
`, header, family(t.font["text"]), family(t.font["display"]))
	b.WriteString("    object color {\n")
	for _, p := range t.colors {
		c := decode[color](p.v)
		fmt.Fprintf(&b, "        val %s = MpColor(%s, %s, %s, %s)\n", camel(p.k), col(c.Light), col(c.Dark), col(c.contrast(false)), col(c.contrast(true)))
	}
	b.WriteString("    }\n    object type {\n")
	for _, p := range t.typeScale {
		s := decode[[4]float64](p.v)
		fmt.Fprintf(&b, "        val %s = MpType(%s.sp, %s.sp, FontWeight(%s), %sf)\n", camel(p.k), num(s[0]), num(s[1]), num(s[2]), num(s[3]))
	}
	var sp []string
	for _, s := range nums(decode[[]float64](field(t.root, "space"))) {
		sp = append(sp, s+".dp")
	}
	fmt.Fprintf(&b, "    }\n    val space = listOf(%s)\n    /** Corners are continuous (a squircle shape). */\n    object radius {\n", strings.Join(sp, ", "))
	for _, p := range t.radius {
		fmt.Fprintf(&b, "        val %s = %s.dp\n", ident(p.k, "r"), string(p.v))
	}
	for _, p := range t.shapes {
		fmt.Fprintf(&b, "        val %s = %s.dp\n", camel(p.k), string(p.v))
	}
	b.WriteString("    }\n")
	for _, g := range []string{"control", "icon"} {
		fmt.Fprintf(&b, "    object %s {\n", g)
		for _, p := range object(field(t.root, g)) {
			fmt.Fprintf(&b, "        val %s = %s.dp\n", camel(p.k), string(p.v))
		}
		b.WriteString("    }\n")
	}
	b.WriteString("    /** Milliseconds. */\n    object duration {\n")
	for _, p := range object(field(t.root, "duration")) {
		fmt.Fprintf(&b, "        const val %s = %s\n", camel(p.k), string(p.v))
	}
	b.WriteString("    }\n    object ease {\n")
	for _, p := range t.eases {
		if p.v[0] == '[' {
			c := decode[[4]float64](p.v)
			fmt.Fprintf(&b, "        val %s = MpCurve(%sf, %sf, %sf, %sf)\n", kotlinName(camel(p.k)), num(c[0]), num(c[1]), num(c[2]), num(c[3]))
		} else {
			s := decode[spring](p.v)
			w := 2 * math.Pi / s.Response
			k := w * w
			fmt.Fprintf(&b, "        val %s = MpSpring(%sf, %sf)\n", camel(p.k), num(s.Damping), strconv.FormatFloat(k, 'f', 1, 64))
		}
	}
	b.WriteString("    }\n    object shadow {\n")
	sl := func(css string) string {
		var out []string
		for _, l := range layers(css) {
			out = append(out, fmt.Sprintf("MpShadowLayer(%s.dp, %s.dp, %s.dp, %s)", num(l.x), num(l.y), num(l.blur), col(l.color)))
		}
		return "listOf(" + strings.Join(out, ", ") + ")"
	}
	for _, p := range t.shadows {
		s := decode[color](p.v)
		fmt.Fprintf(&b, "        val %s = MpShadow(%s, %s)\n", ident(p.k, "s"), sl(s.Light), sl(s.Dark))
	}
	b.WriteString("    }\n}\n")
	return b.String()
}

// ---- small helpers ----

func camel(k string) string {
	parts := strings.Split(k, "-")
	for i := 1; i < len(parts); i++ {
		parts[i] = strings.ToUpper(parts[i][:1]) + parts[i][1:]
	}
	return strings.Join(parts, "")
}

// ident is a key as a name: one that starts with a digit gets a prefix.
func ident(k, prefix string) string {
	if k[0] >= '0' && k[0] <= '9' {
		return prefix + k
	}
	return camel(k)
}

func swiftName(k string) string {
	if k == "in" {
		return "`in`"
	}
	return k
}

func kotlinName(k string) string { return swiftName(k) }

// family is the first family of a CSS font stack.
func family(stack string) string { return strings.Trim(strings.Split(stack, ",")[0], `" `) }

func num(f float64) string { return strconv.FormatFloat(f, 'f', -1, 64) }

func f4(f float64) string { return strconv.FormatFloat(math.Round(f*10000)/10000, 'f', -1, 64) }

func nums(fs []float64) []string {
	out := make([]string, len(fs))
	for i, f := range fs {
		out[i] = num(f)
	}
	return out
}

func pick(dark bool, light, d string) string {
	if dark {
		return d
	}
	return light
}

func or(a, b string) string {
	if a != "" {
		return a
	}
	return b
}

func write(path, s string) { check(os.WriteFile(path, []byte(s), 0o644)) }

func must[T any](v T, err error) T {
	check(err)
	return v
}

func check(err error) {
	if err != nil {
		panic(err)
	}
}
